#!/usr/bin/env python3
from __future__ import annotations

import shutil
import subprocess
import sys
from datetime import datetime
from pathlib import Path

ROOT = Path.cwd().resolve()
if not (ROOT / "services/oncotwin-api/src/oncotwin_api/main.py").is_file():
    raise SystemExit("Run this installer from /home/henryxie/OncoTwin-backup")

STAMP = datetime.now().strftime("%Y%m%d_%H%M%S")
BACKUP = ROOT / "artifacts/app_cp4" / f"preinstall_{STAMP}"
BACKUP.mkdir(parents=True, exist_ok=True)

TO_BACKUP = ['services/oncotwin-api/src/oncotwin_api/config.py', 'services/oncotwin-api/src/oncotwin_api/models.py', 'services/oncotwin-api/src/oncotwin_api/processing.py', 'services/oncotwin-api/src/oncotwin_api/main.py', 'apps/oncotwin-web/lib/types.ts', 'apps/oncotwin-web/app/app/forecast/page.tsx', 'apps/oncotwin-web/app/app/update/page.tsx', 'apps/oncotwin-web/app/app/records/page.tsx']
for rel in TO_BACKUP:
    src = ROOT / rel
    if src.exists():
        dst = BACKUP / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(src, dst)

def write(rel: str, text: str, executable: bool = False) -> None:
    p = ROOT / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text)
    if executable: p.chmod(0o755)
    print(f"WROTE {rel}")

def append_once(rel: str, marker: str, text: str) -> None:
    p = ROOT / rel
    s = p.read_text()
    if marker in s:
        print(f"SKIP {rel}: marker already present")
        return
    p.write_text(s.rstrip() + "\n" + text.rstrip() + "\n")
    print(f"PATCHED {rel}")

